package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GzTrackerTest
{
	private static final GzTracker.Settings SETTINGS = new GzTracker.Settings(90_000L, true, 40);

	@Test
	public void attributesGzToOpenBroadcast()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "Zezima has received a drop: Twisted bow", 1_000L);

		assertTrue(t.onClanChat("Nick", "gz", 2_000L, SETTINGS));
		assertTrue(t.onClanChat("Bob", "GZZZ", 3_000L, SETTINGS));

		assertEquals(1, (int) t.getAllTime().getGiven().get("Nick"));
		assertEquals(1, (int) t.getAllTime().getGiven().get("Bob"));
		assertEquals(2, (int) t.getAllTime().getReceived().get("Zezima"));
		assertEquals(2, t.getAllTime().getRecent().get(0).getGzCount());
		assertEquals(2, t.getSession().totalGiven());
	}

	@Test
	public void windowExpires()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		assertTrue(t.onClanChat("Nick", "gz", 1_000L + 90_000L + 1, SETTINGS));

		// given still counts, received does not
		assertEquals(1, (int) t.getAllTime().getGiven().get("Nick"));
		assertNull(t.getAllTime().getReceived().get("Zezima"));
		assertNull(t.currentWindow(200_000L, 90_000L));
	}

	@Test
	public void oneGzPerPersonPerBroadcast()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		t.onClanChat("Nick", "gz", 2_000L, SETTINGS);
		t.onClanChat("Nick", "gz again", 3_000L, SETTINGS);

		assertEquals(2, (int) t.getAllTime().getGiven().get("Nick"));
		assertEquals(1, (int) t.getAllTime().getReceived().get("Zezima"));

		GzTracker.Settings noDedupe = new GzTracker.Settings(90_000L, false, 40);
		t.onClanChat("Nick", "gz", 4_000L, noDedupe);
		assertEquals(2, (int) t.getAllTime().getReceived().get("Zezima"));
	}

	@Test
	public void selfGzDoesNotCountAsReceived()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		t.onClanChat("Zezima", "gz me", 2_000L, SETTINGS);
		assertNull(t.getAllTime().getReceived().get("Zezima"));
		assertEquals(1, (int) t.getAllTime().getGiven().get("Zezima"));
	}

	@Test
	public void newBroadcastReplacesWindow()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("A", "a", 1_000L);
		t.onBroadcast("B", "b", 2_000L);
		t.onClanChat("Nick", "gz", 3_000L, SETTINGS);
		assertNull(t.getAllTime().getReceived().get("A"));
		assertEquals(1, (int) t.getAllTime().getReceived().get("B"));
	}

	@Test
	public void nonGzIsIgnoredAndRecentIsCapped()
	{
		GzTracker t = new GzTracker();
		assertFalse(t.onClanChat("Nick", "anyone for tob?", 1_000L, SETTINGS));
		for (int i = 0; i < 20; i++)
		{
			t.onBroadcast("P" + i, "x", i);
		}
		assertEquals(GzStats.MAX_RECENT, t.getAllTime().getRecent().size());
		assertEquals("P19", t.getAllTime().getRecent().get(0).getSubject());
		assertNull(t.getAllTime().topGiver());
	}

	@Test
	public void lastGzIsRecordedForIndicator()
	{
		GzTracker t = new GzTracker();
		t.onClanChat("Nick", "gz", 5L, SETTINGS);
		assertEquals(5L, t.getLastGzTime());
		assertEquals("Nick", t.getLastGzGiver());
		assertNull(t.getLastGzSubject());

		t.onBroadcast("Zezima", "drop", 10L);
		t.onClanChat("Bob", "grats", 11L, SETTINGS);
		assertEquals("Bob", t.getLastGzGiver());
		assertEquals("Zezima", t.getLastGzSubject());
	}

	@Test
	public void topGiverAndReset()
	{
		GzTracker t = new GzTracker();
		t.onClanChat("Nick", "gz", 1L, SETTINGS);
		t.onClanChat("Nick", "gz", 2L, SETTINGS);
		t.onClanChat("Bob", "gz", 3L, SETTINGS);
		assertEquals("Nick", t.getAllTime().topGiver());
		t.resetAllTime();
		assertEquals(0, t.getAllTime().totalGiven());
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class BroadcastParserTest
{
	@Test
	public void drops()
	{
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has received a drop: Twisted bow (1,000,000,000 coins)."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima received a drop: Dragon claws (100,000,000 coins)"));
	}

	@Test
	public void levelsAndPets()
	{
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has reached level 99 in Attack."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has reached a total level of 2277."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has a funny feeling like they're being followed: Vorki at 1,000 kill count."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima feels something weird sneaking into their backpack: Rocky at 100 pickpockets."));
	}

	@Test
	public void achievements()
	{
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has completed a quest: Dragon Slayer II"));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has completed the Elite Lumbridge & Draynor diary."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima has achieved a new personal best: Theatre of Blood 15:23."));
		assertEquals("Zezima", BroadcastParser.subjectOf("Zezima received a new collection log item: Dragon pickaxe (123/1477)"));
	}

	@Test
	public void namesWithSpacesNbspAndTags()
	{
		assertEquals("Iron Nick", BroadcastParser.subjectOf("Iron Nick has reached level 99 in Slayer."));
		assertEquals("Iron Nick", BroadcastParser.subjectOf("<col=ff0000>Iron Nick</col> has reached level 99 in Slayer."));
		assertEquals("Iron Nick", BroadcastParser.subjectOf("Iron_Nick has reached level 99 in Slayer."));
	}

	@Test
	public void ignoredBroadcasts()
	{
		assertNull(BroadcastParser.subjectOf("Zezima has deposited 1,000,000 coins into the coffer."));
		assertNull(BroadcastParser.subjectOf("Zezima has withdrawn 1,000,000 coins from the coffer."));
		assertNull(BroadcastParser.subjectOf("Zezima has been invited into the clan by Nick."));
		assertNull(BroadcastParser.subjectOf("Zezima has left the clan."));
		assertNull(BroadcastParser.subjectOf("Zezima has been kicked from the clan by Nick."));
		assertNull(BroadcastParser.subjectOf("Zezima has died and lost their Hardcore Ironman status."));
		assertNull(BroadcastParser.subjectOf("Zezima has been defeated by Nick in The Wilderness."));
		assertNull(BroadcastParser.subjectOf(""));
		assertNull(BroadcastParser.subjectOf(null));
		assertNull(BroadcastParser.subjectOf("Welcome to The Core!"));
		assertNull(BroadcastParser.subjectOf("A very long sentence that does not start with a name has something"));
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GzDetectorTest
{
	private static final int MAX = 40;

	@Test
	public void plainForms()
	{
		assertTrue(GzDetector.isGz("gz", MAX));
		assertTrue(GzDetector.isGz("GZ", MAX));
		assertTrue(GzDetector.isGz("Gz!", MAX));
		assertTrue(GzDetector.isGz("grats", MAX));
		assertTrue(GzDetector.isGz("gratz", MAX));
		assertTrue(GzDetector.isGz("congrats", MAX));
		assertTrue(GzDetector.isGz("Congratulations", MAX));
	}

	@Test
	public void repeatedLettersAndPunctuation()
	{
		assertTrue(GzDetector.isGz("GZZZZZ!!!", MAX));
		assertTrue(GzDetector.isGz("gzzzzzzzzzz", MAX));
		assertTrue(GzDetector.isGz("graaaats", MAX));
		assertTrue(GzDetector.isGz("gz gz gz", MAX));
		assertTrue(GzDetector.isGz("ggzz", MAX));
	}

	@Test
	public void withinShortSentences()
	{
		assertTrue(GzDetector.isGz("big gz mate", MAX));
		assertTrue(GzDetector.isGz("gz on the pet", MAX));
		assertTrue(GzDetector.isGz("huge grats!!", MAX));
		assertTrue(GzDetector.isGz("wow gz :)", MAX));
	}

	@Test
	public void notGz()
	{
		assertFalse(GzDetector.isGz("", MAX));
		assertFalse(GzDetector.isGz("   ", MAX));
		assertFalse(GzDetector.isGz(null, MAX));
		assertFalse(GzDetector.isGz("anyone doing cox?", MAX));
		assertFalse(GzDetector.isGz("lol", MAX));
		assertFalse(GzDetector.isGz("gzu", MAX));
		assertFalse(GzDetector.isGz("gzeg is my friend", MAX));
	}

	@Test
	public void longMessagesAreIgnored()
	{
		assertFalse(GzDetector.isGz("did anyone see the gz that guy got earlier in the raid lol", MAX));
		assertTrue(GzDetector.isGz("did anyone see the gz that guy got earlier in the raid lol", 200));
	}

	@Test
	public void normalizeCollapsesRepeats()
	{
		assertEquals("gz", GzDetector.normalize("GZZZZ!!!"));
		assertEquals("big gz mate", GzDetector.normalize("  Big   GZZ,  mate "));
		assertEquals("grats", GzDetector.normalize("graaaatsss"));
	}
}

