package com.corclan.icons;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.clan.ClanRank;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.ImageUtil;

/**
 * Loads the CoR chat icons from resources, registers them with RuneLite's {@link ChatIconManager}
 * exactly once, and maps clan ranks / config keys to the {@code <img=N>} index used in chat.
 * Everything here is local to this client; nothing is sent anywhere.
 */
@Slf4j
@Singleton
public class ClanIconService
{
	/** Chat icons are drawn at this size by the game. */
	private static final int ICON_SIZE = 11;

	/** Red rhino: owner, deputy owner and administrators. */
	public static final String KEY_STAFF = "staff";
	/** Blue rhino: every other member and guests. */
	public static final String KEY_MEMBER = "member";
	public static final String KEY_GZ_KING = "gzking";

	private static final List<String> RANK_KEYS = Arrays.asList(KEY_STAFF, KEY_MEMBER);

	public static final String KEY_FOUNDER = "founder";
	public static final String KEY_DEV = "dev";

	/** Keys a clan admin can use in the "Member icons" config box. */
	public static final List<String> MEMBER_KEYS = Collections.unmodifiableList(Arrays.asList(
		"crown", "trophy", "star", "skull", "gem", "fire", KEY_FOUNDER, KEY_DEV));

	private final ChatIconManager chatIconManager;
	private final Map<String, Integer> iconIds = new HashMap<>();

	@Inject
	public ClanIconService(ChatIconManager chatIconManager)
	{
		this.chatIconManager = chatIconManager;
	}

	/**
	 * Registers all icons with the chat icon manager. Safe to call repeatedly; the ids are cached
	 * for the lifetime of the client so toggling the plugin never registers duplicates.
	 */
	public synchronized void ensureRegistered()
	{
		if (!iconIds.isEmpty())
		{
			return;
		}
		for (String key : RANK_KEYS)
		{
			register(key, "rank_" + key + ".png");
		}
		for (String key : MEMBER_KEYS)
		{
			register(key, "member_" + key + ".png");
		}
		register(KEY_GZ_KING, "member_gzking.png");
		log.debug("Registered {} CoR chat icons", iconIds.size());
	}

	/** Absolute path: this class sits in com.corclan.icons but the PNGs live in com/corclan/. */
	private static final String RESOURCE_DIR = "/com/corclan/";

	private void register(String key, String resource)
	{
		try
		{
			BufferedImage img = ImageUtil.loadImageResource(ClanIconService.class, RESOURCE_DIR + resource);
			if (img.getHeight() != ICON_SIZE)
			{
				// keep width proportional: wordmark icons may be wider than they are tall
				int width = Math.max(1, Math.round(img.getWidth() * (float) ICON_SIZE / img.getHeight()));
				img = ImageUtil.resizeImage(img, width, ICON_SIZE);
			}
			iconIds.put(key, chatIconManager.registerChatIcon(img));
		}
		catch (RuntimeException ex)
		{
			log.warn("Could not load CoR icon {}", resource, ex);
		}
	}

	/**
	 * @return the mod icon index for an icon key, or -1 if that icon is unknown or the client has
	 * not finished loading its chat icons yet
	 */
	public int indexFor(String key)
	{
		if (key == null)
		{
			return -1;
		}
		Integer id = iconIds.get(key);
		if (id == null)
		{
			return -1;
		}
		return chatIconManager.chatIconIndex(id);
	}

	/** @return the {@code <img=N>} tag for an icon key, or null when {@link #indexFor} is -1 */
	public String tagFor(String key)
	{
		int index = indexFor(key);
		return index < 0 ? null : "<img=" + index + ">";
	}

	public boolean isMemberKey(String key)
	{
		return key != null && MEMBER_KEYS.contains(key);
	}

	/**
	 * Maps a clan rank to a rank icon key. Clan ranks are ints: guests are negative, normal member
	 * ranks count up from 0, administrators are 100+, deputy owner 125, owner 126. J-Mods (127)
	 * keep their own icon.
	 */
	public static String rankKey(ClanRank rank)
	{
		if (rank == null || ClanRank.JMOD.equals(rank))
		{
			return null;
		}
		return rank.getRank() >= ClanRank.ADMINISTRATOR.getRank() ? KEY_STAFF : KEY_MEMBER;
	}
}

package com.corclan.gz;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure text logic that turns a clan system broadcast ("Zezima has received a drop: ...") into the
 * name of the member being congratulated, or {@code null} when the broadcast is not gz-worthy
 * (coffer transactions, invites, kicks, deaths ...).
 */
public final class BroadcastParser
{
	/** Broadcasts containing any of these are never gz-worthy. */
	private static final List<String> IGNORE_FRAGMENTS = Arrays.asList(
		"coffer",
		"has been invited",
		"has invited",
		"has left the clan",
		"has been kicked",
		"has been removed",
		"has been promoted",
		"has been demoted",
		"has died",
		"has been defeated",
		"lost their hardcore",
		"welcome to",
		"has logged",
		"is now"
	);

	/** "&lt;name&gt; has ..." / "&lt;name&gt; received ..." / "&lt;name&gt; feels ..." */
	private static final Pattern SUBJECT = Pattern.compile(
		"^(.+?)\\s+(?:has|have|received|feels|just|got)\\b",
		Pattern.CASE_INSENSITIVE);

	private BroadcastParser()
	{
	}

	/**
	 * @return the member the broadcast is about, or {@code null} if the broadcast should be ignored
	 */
	public static String subjectOf(String broadcast)
	{
		if (broadcast == null)
		{
			return null;
		}
		String text = clean(broadcast);
		if (text.isEmpty())
		{
			return null;
		}
		String lower = text.toLowerCase(Locale.ROOT);
		for (String fragment : IGNORE_FRAGMENTS)
		{
			if (lower.contains(fragment))
			{
				return null;
			}
		}
		Matcher m = SUBJECT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String subject = m.group(1).trim();
		// player names are 1-12 chars; anything longer is not a name
		if (subject.isEmpty() || subject.length() > 12)
		{
			return null;
		}
		return subject;
	}

	/** Strips tags, replaces non-breaking spaces / underscores and collapses whitespace. */
	public static String clean(String text)
	{
		return text
			.replaceAll("<[^>]*>", "")
			.replace(' ', ' ')
			.replace('_', ' ')
			.replaceAll("\\s+", " ")
			.trim();
	}
}

package com.corclan.gz;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/** Counters for gz's given and received. Serialized to RuneLite config as JSON with Gson. */
public class GzStats
{
	public static final int MAX_RECENT = 10;

	private Map<String, Integer> given = new HashMap<>();
	private Map<String, Integer> received = new HashMap<>();
	private List<BroadcastRecord> recent = new ArrayList<>();

	public Map<String, Integer> getGiven()
	{
		if (given == null)
		{
			given = new HashMap<>();
		}
		return given;
	}

	public Map<String, Integer> getReceived()
	{
		if (received == null)
		{
			received = new HashMap<>();
		}
		return received;
	}

	public List<BroadcastRecord> getRecent()
	{
		if (recent == null)
		{
			recent = new ArrayList<>();
		}
		return recent;
	}

	void addGiven(String name)
	{
		getGiven().merge(name, 1, Integer::sum);
	}

	void addReceived(String name)
	{
		getReceived().merge(name, 1, Integer::sum);
	}

	void addRecent(BroadcastRecord record)
	{
		List<BroadcastRecord> list = getRecent();
		list.add(0, record);
		while (list.size() > MAX_RECENT)
		{
			list.remove(list.size() - 1);
		}
	}

	public int totalGiven()
	{
		return getGiven().values().stream().mapToInt(Integer::intValue).sum();
	}

	public int totalReceived()
	{
		return getReceived().values().stream().mapToInt(Integer::intValue).sum();
	}

	/** Top entries, highest first, ties broken by name. */
	public static List<Map.Entry<String, Integer>> top(Map<String, Integer> counts, int limit)
	{
		return counts.entrySet().stream()
			.sorted(Comparator.comparing((Map.Entry<String, Integer> e) -> e.getValue()).reversed()
				.thenComparing(Map.Entry::getKey))
			.limit(limit)
			.collect(Collectors.toList());
	}

	public String topGiver()
	{
		List<Map.Entry<String, Integer>> top = top(getGiven(), 1);
		return top.isEmpty() ? null : top.get(0).getKey();
	}
}

package com.corclan.gz;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Pure text logic that decides whether a clan chat line is a "gz" (congratulations).
 * No RuneLite dependencies so it can be unit tested directly.
 */
public final class GzDetector
{
	private static final Set<String> GZ_TOKENS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"gz", "gzs",
		"grats", "gratz", "grtz", "gratulations", "gratulation",
		"congrats", "congratz", "congratulations", "congratulation"
	)));

	private GzDetector()
	{
	}

	/**
	 * @param message   raw chat message (may contain caps, punctuation, repeated letters)
	 * @param maxLength messages longer than this are never counted, so "gz" buried in a long
	 *                  unrelated sentence does not count
	 */
	public static boolean isGz(String message, int maxLength)
	{
		if (message == null)
		{
			return false;
		}
		String trimmed = message.trim();
		if (trimmed.isEmpty() || trimmed.length() > maxLength)
		{
			return false;
		}
		String normalized = normalize(trimmed);
		if (normalized.isEmpty())
		{
			return false;
		}
		for (String token : normalized.split(" "))
		{
			if (GZ_TOKENS.contains(token))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Lower-cases, drops everything except letters and spaces, and collapses runs of the same
	 * letter ("gzzzz" -> "gz", "graaats" -> "grats").
	 */
	static String normalize(String message)
	{
		String lower = message.toLowerCase(Locale.ROOT);
		StringBuilder sb = new StringBuilder(lower.length());
		char prev = 0;
		for (int i = 0; i < lower.length(); i++)
		{
			char c = lower.charAt(i);
			boolean letter = c >= 'a' && c <= 'z';
			if (!letter && c != ' ')
			{
				// punctuation / digits / emoji act as separators
				c = ' ';
			}
			if (c == prev && c != ' ')
			{
				continue;
			}
			if (c == ' ' && prev == ' ')
			{
				continue;
			}
			sb.append(c);
			prev = c;
		}
		return sb.toString().trim();
	}
}

package com.corclan.gz;

/**
 * Attributes gz messages to the most recent clan broadcast while its window is open.
 * Pure Java: the plugin feeds it chat events and persists {@link #getAllTime()} when
 * {@link #onClanChat} reports a change.
 */
public class GzTracker
{
	private GzStats allTime = new GzStats();
	private GzStats session = new GzStats();
	private BroadcastRecord current;

	// last counted gz, for the on-screen indicator
	private long lastGzTime;
	private String lastGzGiver;
	private String lastGzSubject;

	public long getLastGzTime()
	{
		return lastGzTime;
	}

	public String getLastGzGiver()
	{
		return lastGzGiver;
	}

	/** Who the last gz was credited to, or null if no broadcast window was open. */
	public String getLastGzSubject()
	{
		return lastGzSubject;
	}

	public void load(GzStats stats)
	{
		allTime = stats != null ? stats : new GzStats();
		session = new GzStats();
		current = null;
	}

	public GzStats getAllTime()
	{
		return allTime;
	}

	public GzStats getSession()
	{
		return session;
	}

	public void resetAllTime()
	{
		allTime = new GzStats();
		current = null;
	}

	public void resetSession()
	{
		session = new GzStats();
	}

	/** @return the broadcast currently accepting gz's, or null if none / expired */
	public BroadcastRecord currentWindow(long now, long windowMillis)
	{
		if (current != null && current.isOpen(now, windowMillis))
		{
			return current;
		}
		return null;
	}

	/**
	 * @param subject the member being congratulated (from {@link BroadcastParser#subjectOf})
	 * @return the record that now accepts gz's
	 */
	public BroadcastRecord onBroadcast(String subject, String text, long now)
	{
		BroadcastRecord record = new BroadcastRecord(subject, text, now);
		current = record;
		allTime.addRecent(record);
		session.addRecent(record);
		return record;
	}

	/**
	 * @return true if any counter changed (caller should persist + refresh UI)
	 */
	public boolean onClanChat(String sender, String message, long now, Settings settings)
	{
		if (sender == null || sender.isEmpty() || !GzDetector.isGz(message, settings.maxMessageLength))
		{
			return false;
		}
		allTime.addGiven(sender);
		session.addGiven(sender);
		lastGzTime = now;
		lastGzGiver = sender;
		lastGzSubject = null;

		BroadcastRecord window = currentWindow(now, settings.windowMillis);
		if (window != null
			&& !sender.equalsIgnoreCase(window.getSubject())
			&& (!settings.oneGzPerPersonPerBroadcast || !window.getGivers().contains(sender)))
		{
			window.addGz(sender);
			allTime.addReceived(window.getSubject());
			session.addReceived(window.getSubject());
			lastGzSubject = window.getSubject();
		}
		return true;
	}

	/** Snapshot of the config values the tracker needs. */
	public static final class Settings
	{
		public final long windowMillis;
		public final boolean oneGzPerPersonPerBroadcast;
		public final int maxMessageLength;

		public Settings(long windowMillis, boolean oneGzPerPersonPerBroadcast, int maxMessageLength)
		{
			this.windowMillis = windowMillis;
			this.oneGzPerPersonPerBroadcast = oneGzPerPersonPerBroadcast;
			this.maxMessageLength = maxMessageLength;
		}
	}
}

package com.corclan.gz;

import java.util.HashSet;
import java.util.Set;

/** One clan broadcast and the gz's that were attributed to it. Serialized with Gson. */
public class BroadcastRecord
{
	private String subject;
	private String text;
	private long timestamp;
	private int gzCount;
	private Set<String> givers = new HashSet<>();

	public BroadcastRecord()
	{
	}

	public BroadcastRecord(String subject, String text, long timestamp)
	{
		this.subject = subject;
		this.text = text;
		this.timestamp = timestamp;
	}

	public String getSubject()
	{
		return subject;
	}

	public String getText()
	{
		return text;
	}

	public long getTimestamp()
	{
		return timestamp;
	}

	public int getGzCount()
	{
		return gzCount;
	}

	public Set<String> getGivers()
	{
		if (givers == null)
		{
			givers = new HashSet<>();
		}
		return givers;
	}

	void addGz(String giver)
	{
		gzCount++;
		getGivers().add(giver);
	}

	public boolean isOpen(long now, long windowMillis)
	{
		return now - timestamp <= windowMillis;
	}
}

